  /// key is on the device.
  Future<bool> prefetch({
    required List<String> names,
    required FutureOr<bool> Function(ProvingKeyProgress) progress,
  }) => RustLib.instance.api.zolanaMobileProvingKeysPrefetch(
    that: this,
    names: names,
    progress: progress,
